class LinkedStack {
  constructor() { this._top = null; this._size = 0; }
  push(val) {
    this._top = new ListNode(val, this._top);
    this._size++;
  }
  pop() {
    if (!this._top) return undefined;
    const val = this._top.val;
    this._top = this._top.next;
    this._size--;
    return val;
  }
  peek()    { return this._top ? this._top.val : undefined; }
  isEmpty() { return this._top === null; }
  get size(){ return this._size; }
}

function crossVerify(operations) {
  const a = new ArrayStack();
  const b = new LinkedStack();
  for (const o of operations) {
    let resultA, resultB;
    if (o.op === 'push') { a.push(o.val); b.push(o.val); resultA = resultB = undefined; }
    else if (o.op === 'pop') { resultA = a.pop(); resultB = b.pop(); }
    else if (o.op === 'peek') { resultA = a.peek(); resultB = b.peek(); }
    else if (o.op === 'isEmpty') { resultA = a.isEmpty(); resultB = b.isEmpty(); }
    if (resultA !== resultB) return false;
  }
  return true;
}

