class MinStack {
  constructor() { this._stack = []; this._minStack = []; }
  push(val) {
    this._stack.push(val);
    const currentMin = this._minStack.length === 0
      ? val
      : Math.min(val, this._minStack[this._minStack.length - 1]);
    this._minStack.push(currentMin);
  }
  pop() {
    this._stack.pop();
    this._minStack.pop();
  }
  top()    { return this._stack[this._stack.length - 1]; }
  getMin() { return this._minStack[this._minStack.length - 1]; }
}

class MinStackOptimised {
  constructor() { this._stack = []; this._minStack = []; }
  push(val) {
    this._stack.push(val);
    if (this._minStack.length === 0 ||
        val <= this._minStack[this._minStack.length - 1]) {
      this._minStack.push(val);
    }
  }
  pop() {
    const val = this._stack.pop();
    if (val === this._minStack[this._minStack.length - 1]) {
      this._minStack.pop();
    }
  }
  getMin() { return this._minStack[this._minStack.length - 1]; }
}

function stressTestEquivalence(operations) {
  const a = new MinStack();
  const b = new MinStackOptimised();
  for (const o of operations) {
    if (o.op === 'push') { a.push(o.val); b.push(o.val); }
    else if (o.op === 'pop') { a.pop(); b.pop(); }
    else if (o.op === 'getMin') {
      if (a.getMin() !== b.getMin()) return false;
    }
  }
  return true;
}

