class Queue {
  constructor() {
    this._data = {};
    this._head = 0;
    this._tail = 0;
  }
  enqueue(val) {
    this._data[this._tail] = val;
    this._tail++;
  }
  dequeue() {
    if (this.isEmpty()) return undefined;
    const val = this._data[this._head];
    delete this._data[this._head];
    this._head++;
    return val;
  }
  front()    { return this._data[this._head]; }
  isEmpty()  { return this._head === this._tail; }
  get size() { return this._tail - this._head; }
}

class PrintJobScheduler {
  constructor() {
    this._queue = new Queue();
  }
  submitJob(jobName) {
    this._queue.enqueue(jobName);
  }
  processNext() {
    if (this._queue.isEmpty()) return null;
    return this._queue.dequeue();
  }
  pendingCount() {
    return this._queue.size;
  }
}

