class MyQueueImpl {
  constructor() { this._in = []; this._out = []; }
  push(val) { this._in.push(val); }
  pop() {
    this._transfer();
    return this._out.pop();
  }
  peek() {
    this._transfer();
    return this._out[this._out.length - 1];
  }
  empty() { return this._in.length === 0 && this._out.length === 0; }
  _transfer() {
    if (this._out.length === 0) {
      while (this._in.length > 0) {
        this._out.push(this._in.pop());
      }
    }
  }
}

class CircularQueueImpl {
  constructor(capacity) {
    this._buf = new Array(capacity);
    this._cap = capacity;
    this._head = 0;
    this._size = 0;
  }
  get _tail() { return (this._head + this._size) % this._cap; }
  enqueue(val) {
    if (this._size === this._cap) throw new Error('Queue full');
    this._buf[this._tail] = val;
    this._size++;
  }
  dequeue() {
    if (this._size === 0) throw new Error('Queue empty');
    const val = this._buf[this._head];
    this._head = (this._head + 1) % this._cap;
    this._size--;
    return val;
  }
  get size() { return this._size; }
}

function compareQueueOrdering(values, capacity) {
  const q = new MyQueueImpl();
  const c = new CircularQueueImpl(capacity);
  for (const v of values) { q.push(v); c.enqueue(v); }
  const qOut = [];
  const cOut = [];
  while (!q.empty()) qOut.push(q.pop());
  while (c.size > 0) cOut.push(c.dequeue());
  return JSON.stringify(qOut) === JSON.stringify(cOut);
}

