  const result = new Array(n).fill(null).map(() => ({ daysToWait: 0, warmerTemp: null }));
  const stack = [];
  for (let i = 0; i < n; i++) {
    while (stack.length > 0 &&
           temperatures[stack[stack.length - 1]] < temperatures[i]) {
      const prevDay = stack.pop();
      result[prevDay] = { daysToWait: i - prevDay, warmerTemp: temperatures[i] };
    }
    stack.push(i);
  }
  return result;
}

