    stack.push(i);
  }
  return maxArea;
}

function largestRectangleAreaTraced(heights) {
  const h = [...heights, 0];
  const stack = [];
  let maxArea = 0;
  const allAreasComputed = [];
  for (let i = 0; i < h.length; i++) {
    while (stack.length > 0 && h[stack[stack.length - 1]] >= h[i]) {
      const height = h[stack.pop()];
      const width = stack.length === 0
        ? i
        : i - stack[stack.length - 1] - 1;
      const area = height * width;
      allAreasComputed.push(area);
      maxArea = Math.max(maxArea, area);
    }
    stack.push(i);
  }
  return { maxArea, allAreasComputed };
}

